///|
/// Error type for TOML parsing failures.
pub(all) suberror TomlParseError {
  DuplicateKey(line~ : Int, key~ : String)
  ParseError(line~ : Int, msg~ : String)
  UnexpectedChar(line~ : Int, ch~ : Char)
  UnterminatedString(line~ : Int)
  InvalidEscape(line~ : Int, seq~ : String)
  EmptyTableName(line~ : Int)
} derive(Eq, ToJson, Debug)

///|
/// Parse a TOML string into a `@json.Json` value.
///
/// # Panics
/// This function does not panic; errors are raised as `TomlParseError`.
pub fn parse_toml(input : String) -> Json raise TomlParseError {
  let root : Map[String, Json] = {}
  let table_path : Array[String] = []
  let lines = input.split("\n")
  let mut line_num = 0
  for line in lines {
    line_num = line_num + 1
    let trimmed = line.trim()
    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed.starts_with("#") {
      continue
    }
    // Check for table header
    if trimmed.starts_with("[") {
      parse_table_header(trimmed, line_num, root, table_path)
      continue
    }
    // Parse key = value
    parse_key_value(trimmed, line_num, root, table_path)
  }
  Json::object(root)
}

///|
/// Parse a table header like `[owner]` or `[database.settings]`.
fn parse_table_header(
  line : StringView,
  line_num : Int,
  root : Map[String, Json],
  table_path : Array[String],
) -> Unit raise TomlParseError {
  // Remove leading '[' and trailing ']'
  let inner = line[1:line.length() - 1].trim()
  if inner.is_empty() {
    raise EmptyTableName(line=line_num)
  }
  // Clear current path
  table_path.clear()
  // Parse dotted table name
  let parts = inner.split(".")
  for part in parts {
    let key = part.trim().to_string()
    if key.is_empty() {
      raise EmptyTableName(line=line_num)
    }
    table_path.push(key)
  }
}

///|
/// Parse a key-value pair and insert into the TOML structure.
fn parse_key_value(
  line : StringView,
  line_num : Int,
  root : Map[String, Json],
  table_path : Array[String],
) -> Unit raise TomlParseError {
  // Find the first '=' not inside a string
  let eq_pos = find_key_value_separator(line, line_num)
  let key_part = line[:eq_pos].trim()
  let value_part = line[(eq_pos + 1):].trim()

  if key_part.is_empty() {
    raise ParseError(line=line_num, msg="empty key")
  }

  let value = parse_value(value_part, line_num)

  // Resolve dotted key into path segments
  let key_segments = key_part.split(".").to_array()

  // Navigate through table path to find the right sub-object
  let current = navigate_to_table(root, table_path, line_num)

  // Now handle the dotted key segments
  let parent = navigate_dotted_keys(current, key_segments, line_num)

  // Set the final key
  let final_key = key_segments[key_segments.length() - 1].trim().to_string()
  if final_key.is_empty() {
    raise ParseError(line=line_num, msg="empty key segment")
  }
  if parent.contains(final_key) {
    raise DuplicateKey(line=line_num, key=final_key)
  }
  parent[final_key] = value
}

///|
/// Navigate through the table path to find the map where the key should be inserted.
fn navigate_to_table(
  root : Map[String, Json],
  table_path : Array[String],
  line_num : Int,
) -> Map[String, Json] raise TomlParseError {
  let mut current = root
  for i = 0; i < table_path.length(); i = i + 1 {
    let seg = table_path[i]
    match current.get(seg) {
      Some(Json::Object(m)) => current = m
      Some(_) => raise DuplicateKey(line=line_num, key=seg)
      None => {
        let new_obj : Map[String, Json] = {}
        current[seg] = Json::object(new_obj)
        current = new_obj
      }
    }
  }
  current
}

///|
/// Navigate through dotted key segments (except the last) to find the parent map.
fn navigate_dotted_keys(
  root : Map[String, Json],
  key_segments : Array[StringView],
  line_num : Int,
) -> Map[String, Json] raise TomlParseError {
  let mut current = root
  let n = key_segments.length()
  for i = 0; i < n - 1; i = i + 1 {
    let seg = key_segments[i].trim().to_string()
    if seg.is_empty() {
      raise ParseError(line=line_num, msg="empty key segment")
    }
    match current.get(seg) {
      Some(Json::Object(m)) => current = m
      Some(_) => raise DuplicateKey(line=line_num, key=seg)
      None => {
        let new_obj : Map[String, Json] = {}
        current[seg] = Json::object(new_obj)
        current = new_obj
      }
    }
  }
  current
}

///|
/// Find the position of `=` separating key from value, skipping over strings.
fn find_key_value_separator(line : StringView, line_num : Int) -> Int raise TomlParseError {
  let mut in_string = false
  let mut string_char : Char = '"'
  let mut i = 0
  while i < line.length() {
    match line.get_char(i) {
      Some(c) => {
        if in_string {
          if c == string_char {
            in_string = false
          } else if c == '\\' {
            i = i + 1
          }
        } else if c == '"' || c == '\'' {
          in_string = true
          string_char = c
        } else if c == '=' {
          return i
        }
      }
      None => break
    }
    i = i + 1
  }
  raise ParseError(line=line_num, msg="missing '=' separator")
}

///|
/// Parse a TOML value.
fn parse_value(s : StringView, line_num : Int) -> Json raise TomlParseError {
  let trimmed = s.trim()

  // Boolean
  if trimmed == "true" {
    return Json::boolean(true)
  }
  if trimmed == "false" {
    return Json::boolean(false)
  }

  // String (double-quoted)
  if trimmed.starts_with("\"") {
    return Json::string(parse_basic_string(trimmed, line_num))
  }

  // Array
  if trimmed.starts_with("[") {
    return parse_array(trimmed, line_num)
  }

  // Integer
  if is_integer(trimmed) {
    let i = parse_int_strict(trimmed, line_num)
    return Json::number(i.to_double(), repr=trimmed.to_string())
  }

  raise ParseError(line=line_num, msg="unrecognized value: \{trimmed}")
}

///|
/// Check if a string view represents an integer.
fn is_integer(s : StringView) -> Bool {
  if s.is_empty() {
    return false
  }
  let mut start = 0
  if s[0] == ('-' : UInt16) || s[0] == ('+' : UInt16) {
    start = 1
  }
  if start >= s.length() {
    return false
  }
  for i = start; i < s.length(); i = i + 1 {
    let ch = s[i]
    if ch < ('0' : UInt16) || ch > ('9' : UInt16) {
      return false
    }
  }
  true
}

///|
/// Parse an integer string, raising on invalid input.
fn parse_int_strict(s : StringView, line_num : Int) -> Int raise TomlParseError {
  try {
    @string.parse_int(s)
  } catch {
    _ => raise ParseError(line=line_num, msg="invalid integer: \{s}")
  }
}

///|
/// Parse a double-quoted basic string with escape sequences.
fn parse_basic_string(s : StringView, line_num : Int) -> String raise TomlParseError {
  // s starts and ends with '"'
  let inner = s[1:s.length() - 1]
  let buf = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    match inner.get_char(i) {
      Some(ch) => {
        if ch == '\\' {
          i = i + 1
          match inner.get_char(i) {
            Some(next_ch) => match next_ch {
              '"' => buf.write_char('"')
              '\\' => buf.write_char('\\')
              'n' => buf.write_char('\n')
              't' => buf.write_char('\t')
              _ => raise InvalidEscape(line=line_num, seq="\\\{next_ch}")
            }
            None => raise UnterminatedString(line=line_num)
          }
        } else {
          buf.write_char(ch)
        }
      }
      None => raise UnterminatedString(line=line_num)
    }
    i = i + 1
  }
  buf.to_string()
}

///|
/// Parse a TOML array like `[1, 2, 3]` or `["a", "b"]`.
fn parse_array(s : StringView, line_num : Int) -> Json raise TomlParseError {
  // s starts with '[' and ends with ']'
  let inner = s[1:s.length() - 1].trim()
  let arr : Array[Json] = []
  if inner.is_empty() {
    return Json::array(arr)
  }
  // Split by commas, respecting nested brackets and strings
  let elements = split_array_elements(inner, line_num)
  for elem in elements {
    arr.push(parse_value(elem, line_num))
  }
  Json::array(arr)
}

///|
/// Split array elements by commas, respecting strings and nested brackets.
fn split_array_elements(s : StringView, line_num : Int) -> Array[StringView] raise TomlParseError {
  let result : Array[StringView] = []
  let mut depth = 0
  let mut in_string = false
  let mut string_char : Char = '"'
  let mut start = 0
  let mut i = 0
  while i < s.length() {
    match s.get_char(i) {
      Some(ch) => {
        if in_string {
          if ch == string_char {
            in_string = false
          } else if ch == '\\' {
            i = i + 1 // skip escape
          }
        } else if ch == '"' || ch == '\'' {
          in_string = true
          string_char = ch
        } else if ch == '[' {
          depth = depth + 1
        } else if ch == ']' {
          depth = depth - 1
        } else if ch == ',' && depth == 0 {
          result.push(s[start:i].trim())
          start = i + 1
        }
      }
      None => break
    }
    i = i + 1
  }
  // Last element
  let last = s[start:].trim()
  if !last.is_empty() {
    result.push(last)
  }
  result
}

