/// TOML to JSON CLI — reads a file or stdin and prints JSON to stdout.
///
/// Usage:
///   moon run --target native cmd/tomljson -- config.toml
///   moon run --target native cmd/tomljson -- --stdin < config.toml
async fn main {
  let args = @env.args()
  // args[0] is the program name
  if args.length() < 2 {
    eprintln("Usage: tomljson <file> | --stdin")
    return
  }

  let source : String
  if args[1] == "--stdin" {
    source = @stdio.stdin.read_all().text()
  } else {
    let path = args[1]
    try {
      let data = @fs.read_file(path).text()
      source = data
    } catch {
      _ => {
        eprintln("Error: failed to read file '\{path}'")
        return
      }
    }
  }

  let json = try {
    @lib.parse_toml(source)
  } catch {
    TomlParseError::DuplicateKey(line, key) => {
      eprintln("Error: duplicate key '\{key}' at line \{line}")
      return
    }
    TomlParseError::ParseError(line, msg) => {
      eprintln("Error: \{msg} at line \{line}")
      return
    }
    TomlParseError::UnexpectedChar(line, ch) => {
      eprintln("Error: unexpected character '\{ch}' at line \{line}")
      return
    }
    TomlParseError::UnterminatedString(line) => {
      eprintln("Error: unterminated string at line \{line}")
      return
    }
    TomlParseError::InvalidEscape(line, seq) => {
      eprintln("Error: invalid escape sequence '\{seq}' at line \{line}")
      return
    }
    TomlParseError::EmptyTableName(line) => {
      eprintln("Error: empty table name at line \{line}")
      return
    }
  }

  println(json.stringify())
}
