/// TOML to JSON CLI — reads a file or stdin and prints JSON to stdout.
///
/// Usage:
///   moon run --target native cmd/tomljson -- config.toml
///   moon run --target native cmd/tomljson -- --stdin < config.toml
async fn main {
  let args = @env.args()
  if args.length() < 2 {
    let _ = @stdio.stderr.write("Usage: tomljson <file> | --stdin\n")
    return
  }

  let source = if args[1] == "--stdin" {
    @stdio.stdin.read_all().text()
  } else {
    try {
      @fs.read_file(args[1]).text()
    } catch {
      _ => {
        let _ = @stdio.stderr.write("Error: failed to read file '\{args[1]}'\n")
        return
      }
    }
  }

  let json = try {
    @lib.parse_toml(source)
  } catch {
    @lib.TomlParseError::DuplicateKey(line, key) => {
      let _ = @stdio.stderr.write("Error: duplicate key '\{key}' at line \{line}\n")
      return
    }
    @lib.TomlParseError::ParseError(line, msg) => {
      let _ = @stdio.stderr.write("Error: \{msg} at line \{line}\n")
      return
    }
    @lib.TomlParseError::UnexpectedChar(line, ch) => {
      let _ = @stdio.stderr.write("Error: unexpected character '\{ch}' at line \{line}\n")
      return
    }
    @lib.TomlParseError::UnterminatedString(line) => {
      let _ = @stdio.stderr.write("Error: unterminated string at line \{line}\n")
      return
    }
    @lib.TomlParseError::InvalidEscape(line, seq) => {
      let _ = @stdio.stderr.write("Error: invalid escape sequence '\{seq}' at line \{line}\n")
      return
    }
    @lib.TomlParseError::EmptyTableName(line) => {
      let _ = @stdio.stderr.write("Error: empty table name at line \{line}\n")
      return
    }
  }

  println(json.stringify())
}
