fn find_closing_bracket(line : StringView, start : Int, line_num : Int) -> Int raise TomlParseError {
  let mut i = start + 1 // skip opening '['
  while i < line.length() {
    match line.get_char(i) {
      Some(c) => if c == ']' {
        return i
      }
      None => break
    }
    i = i + 1
